import { describe, test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import { memoryFirestore } from './helpers/memoryFirestore.js';
import {
    groupSearchText, sameTokens, searchTokens, tokensUpdate, userSearchText,
} from '../src/services/searchTokens.js';
import { backfillSearchTokens } from '../src/services/searchTokensBackfill.js';

// Generated by the app's Dart searchTokens() (specs/search-tokens-functions.md §4).
const VECTORS = JSON.parse(fs.readFileSync(new URL('./fixtures/search_tokens_vectors.json', import.meta.url)));

describe('searchTokens (parity with the app)', () => {
    test('matches every vector exactly, including order', () => {
        assert.equal(VECTORS.length, 12);
        for (const { input, tokens } of VECTORS) assert.deepEqual(searchTokens(input), tokens, JSON.stringify(input));
    });

    test('output is sorted, unique, and every token is 2 to 15 characters', () => {
        for (const { input } of VECTORS) {
            const tokens = searchTokens(input);
            assert.deepEqual(tokens, [...tokens].sort());
            assert.equal(new Set(tokens).size, tokens.length);
            assert.ok(tokens.every((t) => t.length >= 2 && t.length <= 15));
        }
    });

    test('non-text input gives no tokens', () => {
        for (const bad of [undefined, null, 42]) assert.deepEqual(searchTokens(bad), []);
    });

    test('user text is first and last name; missing fields add nothing', () => {
        const tokens = searchTokens(userSearchText({ first_name: 'Mary', last_name: 'Smith' }));
        for (const t of ['ma', 'mary', 'sm', 'smith']) assert.ok(tokens.includes(t), t);
        const onlyFirst = searchTokens(userSearchText({ first_name: 'Mary' }));
        assert.deepEqual(onlyFirst, ['ma', 'mar', 'mary']);
        assert.ok(!onlyFirst.includes('un') && !onlyFirst.includes('nu'), 'no tokens from undefined/null');
        assert.deepEqual(searchTokens(userSearchText({ first_name: 'Mary', last_name: null })), ['ma', 'mar', 'mary']);
        assert.deepEqual(searchTokens(userSearchText()), []);
    });

    test('group text includes the description, which is optional', () => {
        const tokens = searchTokens(groupSearchText({ name: 'Night Owls', description: 'Late-night readers' }));
        for (const t of ['owls', 'late', 'readers']) assert.ok(tokens.includes(t), t);
        assert.deepEqual(searchTokens(groupSearchText({ name: 'Night Owls' })), VECTORS[0].tokens);
    });

    test('sameTokens and tokensUpdate', () => {
        assert.equal(sameTokens(['a', 'b'], ['a', 'b']), true);
        assert.equal(sameTokens(['b', 'a'], ['a', 'b']), false);
        assert.equal(sameTokens(['a'], ['a', 'b']), false);
        assert.equal(sameTokens(undefined, []), false);

        const correct = searchTokens('Mary Smith');
        assert.equal(tokensUpdate(null, userSearchText), null);
        assert.equal(tokensUpdate({ first_name: 'Mary', last_name: 'Smith', search_tokens: correct }, userSearchText), null);
        assert.deepEqual(tokensUpdate({ first_name: 'Mary', last_name: 'Smith' }, userSearchText), correct);
        assert.deepEqual(tokensUpdate({ first_name: 'Mary', last_name: 'Smith', search_tokens: ['ol', 'old'] }, userSearchText), correct);
        assert.equal(tokensUpdate({ first_name: 'Mary', last_name: 'Smith', search_tokens: correct, last_active: new Date() }, userSearchText), null);
        assert.deepEqual(tokensUpdate({ first_name: '', last_name: '' }, userSearchText), [], 'empty text writes [], not nothing');
        assert.equal(tokensUpdate({ first_name: '', search_tokens: [] }, userSearchText), null);
    });
});

describe('backfillSearchTokens', () => {
    async function seeded() {
        const firestore = memoryFirestore();
        await firestore.collection('users').doc('u1').set({ first_name: 'Mary Ann', last_name: 'Smith-Jones', is_verified: true, last_active: 1 });
        await firestore.collection('users').doc('u2').set({ first_name: 'Sam', last_name: 'Lee', search_tokens: searchTokens('Sam Lee') });
        await firestore.collection('users').doc('u3').set({ first_name: 'Renamed', last_name: 'Person', search_tokens: ['ol', 'old'] });
        await firestore.collection('users').doc('u4').set({ email: 'no-name@example.org' });
        await firestore.collection('challenge_groups').doc('g1').set({ name: 'Night Owls', description: 'Late-night readers', is_public: true, member_ids: ['u1'] });
        await firestore.collection('challenge_groups').doc('g2').set({ name: 'Psalms at noon' });
        return firestore;
    }

    test('a dry run writes nothing; a real run fills every document, writing only search_tokens; a second run writes nothing', async () => {
        const firestore = await seeded();
        const before = JSON.stringify([...firestore.store.entries()]);
        const lines = [];
        const dry = await backfillSearchTokens(firestore, { dryRun: true, verbose: true, log: (l) => lines.push(l) });
        assert.equal(JSON.stringify([...firestore.store.entries()]), before, 'dry run writes nothing');
        assert.deepEqual(dry.users, { scanned: 4, updated: 3, unchanged: 1, changedSince: 0, failed: 0, errors: [] });
        assert.deepEqual(dry.challenge_groups, { scanned: 2, updated: 2, unchanged: 0, changedSince: 0, failed: 0, errors: [] });
        assert.ok(lines.some((l) => l.includes('users/u3') && l.includes('replacing stale tokens')));

        const run = await backfillSearchTokens(firestore);
        assert.equal(run.users.updated, 3);
        assert.equal(run.challenge_groups.updated, 2);
        const u1 = firestore.store.get('users/u1');
        assert.deepEqual(u1.search_tokens, searchTokens('Mary Ann Smith-Jones'));
        assert.ok(['mary', 'smith', 'jones'].every((t) => u1.search_tokens.includes(t)));
        assert.deepEqual({ ...u1, search_tokens: undefined }, { first_name: 'Mary Ann', last_name: 'Smith-Jones', is_verified: true, last_active: 1, search_tokens: undefined }, 'other fields untouched');
        assert.deepEqual(firestore.store.get('users/u3').search_tokens, searchTokens('Renamed Person'));
        assert.deepEqual(firestore.store.get('users/u4').search_tokens, []);
        const g1 = firestore.store.get('challenge_groups/g1').search_tokens;
        assert.ok(['night', 'owls', 'late', 'readers'].every((t) => g1.includes(t)), 'tokens from name and description');
        assert.deepEqual(firestore.store.get('challenge_groups/g1').member_ids, ['u1']);

        const again = await backfillSearchTokens(firestore);
        assert.equal(again.users.updated, 0);
        assert.equal(again.challenge_groups.updated, 0);
        assert.equal(again.users.unchanged, 4);
    });

    test('one collection at a time; unknown collections are refused', async () => {
        const firestore = await seeded();
        const run = await backfillSearchTokens(firestore, { collections: ['challenge_groups'] });
        assert.deepEqual(Object.keys(run), ['challenge_groups']);
        assert.equal(firestore.store.get('users/u1').search_tokens, undefined);
        await assert.rejects(backfillSearchTokens(firestore, { collections: ['prayer_requests'] }), /Not a collection with search tokens/);
    });

    test('a document deleted after being read is not recreated', async () => {
        const firestore = await seeded();
        const bulkWriter = firestore.bulkWriter;
        firestore.bulkWriter = () => {
            const writer = bulkWriter();
            const update = writer.update;
            writer.update = (ref, data) => {
                if (ref.path === 'users/u1') firestore.store.delete('users/u1'); // deleted between the read and the write
                return update(ref, data);
            };
            return writer;
        };
        const run = await backfillSearchTokens(firestore, { collections: ['users'] });
        assert.equal(firestore.store.has('users/u1'), false);
        assert.equal(run.users.changedSince, 1);
        assert.equal(run.users.failed, 0);
        assert.equal(run.users.updated, 2);
    });
});
